import React from 'react';
import SafeLink from './SafeLink';
import { sanitizeHtml, escapeHtml } from '../utils/sanitize';
import catAvatar from '../assets/cc98_avatar_cat.png';

interface PostCardProps {
  id: number;
  authorUsername: string;
  authorAvatarUrl?: string | null;
  floor: number | string;
  content: string;
  createdAt: string;
  updatedAt?: string;
  isTopicAuthor?: boolean;
  onQuote?: (username: string, content: string) => void;
  onDelete?: () => void;
  onEdit?: () => void;
  isDeleting?: boolean;
  currentUserCanModify?: boolean;
  children?: React.ReactNode;

  // New props for Likes and Bookmarks
  likeCount?: number;
  isLikedByCurrentUser?: boolean;
  isBookmarkedByCurrentUser?: boolean;
  onToggleLike?: () => void;
  onToggleBookmark?: () => void;

  // New props for Editing and Reporting
  isEditing?: boolean;
  editContent?: string;
  onEditContentChange?: (val: string) => void;
  onSaveEdit?: () => void;
  onCancelEdit?: () => void;
  onReport?: () => void;
}

/**
 * CC98 经典帖子楼层双栏卡片组件 (绑定真实 API 数据)
 */
export default function PostCard({
  id,
  authorUsername,
  authorAvatarUrl,
  floor,
  content,
  createdAt,
  updatedAt,
  isTopicAuthor = false,
  onQuote,
  onDelete,
  onEdit,
  isDeleting = false,
  currentUserCanModify = false,
  children,
  likeCount,
  isLikedByCurrentUser,
  isBookmarkedByCurrentUser,
  onToggleLike,
  onToggleBookmark,
  isEditing = false,
  editContent = '',
  onEditContentChange,
  onSaveEdit,
  onCancelEdit,
  onReport
}: PostCardProps) {
  // Deterministic user stats based on username hash
  const avatar = authorAvatarUrl || catAvatar;

  const hasLikeApi = onToggleLike !== undefined;
  const likes = likeCount ?? 0;
  const liked = !!isLikedByCurrentUser;

  const handleLike = () => {
    if (hasLikeApi) {
      onToggleLike?.();
    }
  };

